def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    me_c = me.count('C')
    me_d = n - me_c
    last_op = op[-1]
    last_me = me[-1]

    # Detect opponent always cooperating
    if op_d == 0:
        # Exploit near end, otherwise cooperate to maximize mutual score
        if n >= 95:
            return 'D'
        return 'C'

    # Detect opponent always defecting
    if op_c == 0:
        return 'D'

    # Detect near-always-defect
    if n >= 8 and op_c <= 1:
        return 'D'

    # Detect near-always-cooperate
    if n >= 8 and op_d <= max(1, n // 15):
        if n >= 92:
            return 'D'
        return 'C'

    # Count recent opponent cooperation (last 12)
    recent_op = op[-12:] if n >= 12 else op
    rn = len(recent_op)
    rc = recent_op.count('C')
    rd = rn - rc

    # Count current defection streak of opponent
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_d += 1
        else:
            break

    # Count current cooperation streak of opponent
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            streak_c += 1
        else:
            break

    # Detect tit-for-tat style opponents (mimic our previous action)
    if n >= 6:
        mimic = 0
        for i in range(1, n):
            if op[i] == me[i - 1]:
                mimic += 1
        if mimic >= n - 2:
            # Opponent mirrors us. Keeping cooperation works well.
            if n >= 93:
                return 'D'
            return 'C'

    # Endgame exploitation when opponent is cooperative
    if n >= 90:
        if op_c * 5 >= n * 4:
            return 'D'
        if rd >= 3:
            return 'D'
        return 'C'

    # Late game: press advantage if opponent mostly cooperates
    if n >= 75:
        if op_c * 3 >= n * 2:
            # Exploit with some probability but maintain some cooperation
            if rng.random() < 0.3:
                return 'D'
            return 'C'
        if streak_d >= 2:
            return 'D'
        return 'C'

    # Opponent defected last round
    if last_op == 'D':
        # Long defection war: try to break out occasionally
        if streak_d >= 4:
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        if streak_d >= 2:
            return 'D'
        # Single defection from an otherwise cooperative opponent: forgiving retaliation
        if op_d * 4 <= n and me_c > 0:
            # they've mostly cooperated, retaliate once then forgive
            if last_me == 'D':
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round
    if last_op == 'C':
        # If we just defected and they still cooperated, keep cooperating to rebuild
        if last_me == 'D':
            # Continued cooperation from opponent - don't overexploit
            if rd >= 4:
                return 'C'
            return 'C'
        # Opponent has been quite defection-heavy overall
        if op_d * 2 > n:
            if streak_c >= 2:
                return 'C'
            return 'D'
        # Mostly cooperative opponent - cooperate, with rare probing
        if n > 30 and op_d * 5 <= n:
            if rng.random() < 0.04:
                return 'D'
            return 'C'
        return 'C'

    return 'C'
